// The vendored splash's shape (vibefield-splash.js is GENERATED by tooling/splash/vendor.mjs: the
// website's module with the boot's patches, tooling/splash/patches.json). field-app has no allowJs, so
// the part of its api the boot's field door uses is declared here, in the module's own words.

/** Thrown when the splash can't start: `reason` is "no-webgpu" or "no-adapter". */
export declare class SplashUnavailable extends Error {
  constructor(reason: string, message: string);
  readonly reason: string;
}

/** The reveal's look: the mark's opacity (1), the edge's light (0.85), its colour (the look's
 * centre light, 0 … 1 display-encoded) and the tear (0.35, how far the noise moves the edge, a
 * share of its radius). */
export interface SplashLook {
  readonly mark?: number;
  readonly rim?: number;
  readonly ink?: readonly [number, number, number];
  readonly tear?: number;
}

export interface SplashRevealOptions extends SplashLook {
  /** ms (1600) */
  readonly duration?: number;
  /** the front's pace, 0 … 1 → 0 … 1 (t²) */
  readonly ease?: (t: number) => number;
  /** the share of the reveal the mark fades in (0.2) */
  readonly markFade?: number;
}

/** The field's geometry for a frame (the module's `geometry`): its backing store, W × H device px at
 * k device px a CSS px, and its mark's box, LW × LH at MX, MY. */
export interface SplashSize {
  readonly k: number;
  readonly W: number;
  readonly H: number;
  readonly LW: number;
  readonly LH: number;
  readonly MX: number;
  readonly MY: number;
}

/** A frame the field has just drawn, as a pass over it sees it (the patch "post-encode"). */
export interface SplashFrame {
  /** the canvas's texture, the frame drawn in it, its command buffer still open */
  readonly view: GPUTextureView;
  readonly size: SplashSize;
  /** the field's mark, as this frame drew it */
  readonly mark: GPUTexture;
  readonly seconds: number;
}

/** A pass of the caller's own over each frame the field draws, on its device and in its command
 * buffer, before the frame is submitted (the patch "post"). */
export interface SplashPost {
  encode(encoder: GPUCommandEncoder, frame: SplashFrame): void;
}

export interface Splash {
  /** Run the loop from `at` seconds (under reduced motion, one frame at rest). */
  start(at?: number): void;
  stop(): void;
  /** The reveal by hand: `front` 0 (the window whole) … 1 (opened past every corner); the next
   * frame takes it. */
  setReveal(front: number, look?: SplashLook): void;
  /** The next frame now when no loop runs (reduced motion), after what a post pass draws has moved
   * (the patch "redraw"). */
  redraw(): void;
  /** The reveal on the splash's frames: true once the window is open, false if replaced or
   * destroyed first, and at once under reduced motion. Needs a transparent splash. */
  reveal(options?: SplashRevealOptions): Promise<boolean>;
  destroy(): void;
}

export interface SplashOptions {
  readonly fps?: number;
  readonly reducedMotion?: boolean;
  readonly timing?: boolean;
  /** a device the caller owns (and destroys); without one the splash requests its own */
  readonly device?: GPUDevice | null;
  /** premultiplied, so the reveal shows what lies under the canvas */
  readonly transparent?: boolean;
  /** the device pixels the field's backing store stops at */
  readonly budget?: number;
  /** a pass over each frame the field draws; the canvas's texture is then readable by it */
  readonly post?: SplashPost | null;
}

export declare function createSplash(
  canvas: HTMLCanvasElement | OffscreenCanvas,
  options?: SplashOptions,
): Promise<Splash>;
